The whole point is that the token lives in a module closure — not on `window`, not in storage — and is re-obtained from the refresh cookie when the page reloads.

```js
// auth.js — module scope, never assigned to window or localStorage
let accessToken = null;

async function refresh() {
  // the HttpOnly refresh cookie rides along; JS never reads it
  const res = await fetch('/auth/refresh', {
    method: 'POST',
    credentials: 'include',
    headers: { 'X-CSRF-Token': readCsrfCookie() },
  });
  if (!res.ok) throw new Error('session expired');
  accessToken = (await res.json()).accessToken;   // stays in memory only
  return accessToken;
}

export async function apiFetch(path, init = {}) {
  if (!accessToken) await refresh();              // cold start after a reload
  let res = await call(path, init, accessToken);
  if (res.status === 401) {                        // expired mid-session
    await refresh();
    res = await call(path, init, accessToken);
  }
  return res;
}

const call = (path, init, token) =>
  fetch(path, { ...init, headers: { ...init.headers, Authorization: `Bearer ${token}` } });
```

Three things to notice. A page refresh silently re-authenticates through the cookie, so the UX is unaffected. Concurrent 401s should share **one** in-flight refresh promise, or a burst of parallel requests triggers a rotation storm. And nothing here is XSS-proof — script in your origin can call `apiFetch` — it just limits what leaves the machine.
